package com.lojaagro.estoque_api.entities;
import jakarta.persistence.*;import java.math.*;
@Entity@Table(name="pedido_lanchonete_consumo",uniqueConstraints=@UniqueConstraint(name="uk_pedido_consumo_produto",columnNames={"pedido_id","produto_id"}))
public class PedidoLanchoneteConsumo{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="pedido_id",nullable=false)private PedidoLanchonete pedido;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="produto_id",nullable=false)private Produto produto;@Column(nullable=false)private int quantidade;@Column(name="custo_unitario",nullable=false,precision=19,scale=2)private BigDecimal custoUnitario;@Column(nullable=false)private boolean restaurado;protected PedidoLanchoneteConsumo(){}public PedidoLanchoneteConsumo(PedidoLanchonete pedido,Produto produto,int quantidade,BigDecimal custoUnitario){this.pedido=pedido;this.produto=produto;this.quantidade=quantidade;this.custoUnitario=(custoUnitario==null?BigDecimal.ZERO:custoUnitario).setScale(2,RoundingMode.HALF_UP);}public Produto getProduto(){return produto;}public int getQuantidade(){return quantidade;}public BigDecimal getCustoUnitario(){return custoUnitario;}public boolean isRestaurado(){return restaurado;}public void restaurar(){if(restaurado)throw new IllegalArgumentException("Consumo já restaurado.");restaurado=true;}}
